// Package web holds the templates and static files of the gosaml.dev
// server. static/parser.wasm and static/wasm_exec.js are generated by
// deploy.sh before the server is compiled; without them the inspector page
// says so, and everything else works.
package web

import "embed"

// Templates are the html/template pages, under templates/.
//
//go:embed templates
var Templates embed.FS

// Static are the static files, under static/, served at /static/.
//
//go:embed static
var Static embed.FS
